const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const jaen = ee.Geometry.Point([-3.7849, 37.7796]); // Jaén, Spain coordinates
  const buffer = jaen.buffer(5000); // 5km buffer around Jaén
  const startDate = '2023-01-01';
  const endDate = '2023-05-15';

  // 2. Data Acquisition - CHIRPS precipitation data
  const precipCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(buffer);

  // Check collection size
  const colSize = precipCol.size().getInfo();
  console.log(`Images in period: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation
  const totalPrecip = precipCol.sum();

  // Check pixel count
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation in mm, convert to inches
  const meanPrecip = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const precipInches = meanPrecip / 25.4; // Convert mm to inches

  console.log(`Total precipitation: ${meanPrecip.toFixed(1)} mm (${precipInches.toFixed(2)} inches)`);

  // 5. Validation & Final Answer
  if (meanPrecip === null || isNaN(meanPrecip) || precipInches === null || isNaN(precipInches)) {
    console.log("<answer>C3</answer>");
  } else if (precipInches > 3) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
